import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import fg from "fast-glob";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const SOURCE_DIR = path.join(__dirname, "..", "..");
const OUTPUT_PATH = path.join(
  __dirname,
  "..",
  "..",
  "config",
  "env",
  "vars",
  "requiredVars.ts"
);

/**
 * Extracts all unique environment variable keys accessed via `process.env.VAR_NAME`
 * from a given source file, ignoring comments and string literals.
 */
function findEnvVarsInFile(filePath) {
  let content = fs.readFileSync(filePath, "utf-8");

  content = content.replace(/\/\*[\s\S]*?\*\//g, "");

  content = content.replace(/\/\/.*/g, "");

  content = content.replace(/(['"`])(?:\\[\s\S]|(?!\1).)*\1/g, "");

  const matches = content.matchAll(/\bprocess\.env\.([A-Z0-9_]+)\b/g);
  return Array.from(matches, (m) => m[1]);
}

/**
 * Scans project files, collects all referenced `process.env.VAR`,
 * and writes them to a **TypeScript** module as a readonly tuple export.
 */
function generateRequiredEnvVars(outputPath) {
  const allFiles = fg.sync(["**/*.{ts,tsx,js,mjs,cjs}"], {
    cwd: SOURCE_DIR,
    ignore: [
      "node_modules/**",
      "client/**",
      "build/**",
      "dist/**",
      "scripts/**",
      "**/*.d.ts",
    ],
    absolute: true,
  });

  const envVars = new Set();

  for (const file of allFiles) {
    try {
      const vars = findEnvVarsInFile(file);
      vars.forEach((v) => envVars.add(v));
    } catch (error) {
      console.warn(`Skipping unreadable file ${file}: ${error}`);
    }
  }

  const sortedVars = Array.from(envVars).sort();

  const tsContent = `/* Auto-generated by scripts/generate-required-vars.ts */
export const REQUIRED_VARS = [
${sortedVars.map((v) => `  "${v}",`).join("\n")}
] as const;

export type RequiredEnvVar = typeof REQUIRED_VARS[number];
export default REQUIRED_VARS;
`;

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, tsContent, "utf8");

  console.log(`Wrote ${sortedVars.length} required env vars to ${outputPath}`);
}

generateRequiredEnvVars(OUTPUT_PATH);
